mapper.select:
SELECT chapter_id, title, description, course_id, created_at, updated_at
FROM edu.chapters
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.delete:
DELETE FROM edu.chapters
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.update:
UPDATE edu.chapters
SET title = #{title},
    description = #{description},
    updated_at = NOW()
WHERE chapter_id = #{chapterId}
  AND course_id = #{courseId}

mapper.select:
SELECT learning_outcome_id
FROM edu.chapter_learning_outcomes
WHERE chapter_id = #{chapterId}

mapper.delete:
DELETE FROM edu.chapter_learning_outcomes
WHERE chapter_id = #{chapterId}
  AND learning_outcome_id = #{learningOutcomeId}

DELETE FROM edu.exam_matrix_row_learning_outcomes mapping
USING edu.exam_matrix_rows matrix_row
WHERE mapping.exam_matrix_row_id = matrix_row.id
  AND matrix_row.chapter_id = #{chapterId}
  AND mapping.learning_outcome_id = #{learningOutcomeId}
